//! Lookup of a single name in a `from` import.

use ty_module_resolver::{ImportingFile, Module, ModuleName, resolve_module};
use ty_python_core::scope::ScopeId;

use super::{MemberLookupError, ModuleLiteralType, ProgramEnvironment, TypeQualifiers};
use crate::place::{DefinedPlace, Definedness, Place, PlaceAndQualifiers};
use crate::{Db, DefinitionResolution, SemanticModel};

/// The source of an imported name before following any re-exports.
#[derive(Debug)]
pub enum ImportedName<'db> {
    Submodule(Module<'db>),
    /// Bindings in the module named by the `from` clause.
    Member(DefinitionResolution<'db>),
}

impl<'db> SemanticModel<'db> {
    /// Returns the immediate source of a name imported from `module` in `scope`.
    ///
    /// Returns `None` for a dynamic attribute or a name without a source binding.
    pub fn imported_name(
        &self,
        scope: ScopeId<'db>,
        module: Module<'db>,
        name: &str,
    ) -> Option<ImportedName<'db>> {
        let db = self.db();
        if db
            .analysis_settings(self.file())
            .replace_imports_with_any
            .matches(module.name(db))
            .is_include()
        {
            return None;
        }

        match FromImportLookup::resolve(db, &self.program_environment(), scope, module, name, || {})
        {
            FromImportLookup::Submodule(literal) => {
                Some(ImportedName::Submodule(literal.module(db)))
            }
            FromImportLookup::Member { qualifiers, .. }
                if name != "__dict__"
                    && !qualifiers.contains(TypeQualifiers::FROM_MODULE_GETATTR) =>
            {
                self.definitions_for_module_global(module, name)
                    .map(ImportedName::Member)
            }
            _ => None,
        }
    }
}

pub(super) enum FromImportLookup<'db> {
    Submodule(ModuleLiteralType<'db>),
    Member {
        place: DefinedPlace<'db>,
        qualifiers: TypeQualifiers,
        error: Option<MemberLookupError<'db>>,
    },
    Missing(Option<ModuleName>),
}

impl<'db> FromImportLookup<'db> {
    pub(super) fn resolve(
        db: &'db dyn Db,
        env: &ProgramEnvironment<'db>,
        scope: ScopeId<'db>,
        module: Module<'db>,
        name: &str,
        possibly_missing: impl FnOnce(),
    ) -> Self {
        let file = scope.program_file(db);
        let literal = ModuleLiteralType::for_import(db, file, module);

        // Looking up a module's own global import can recurse into that same definition.
        // An import in a function can safely read the module's global bindings.
        let imports_itself =
            module.file(db) == Some(file.file(db)) && scope.file_scope_id(db).is_global();
        let mut from_getattr = None;
        if !imports_itself {
            if let Some(submodule) = literal.imported_submodule_attribute(db, name) {
                return Self::Submodule(submodule);
            }

            let result = literal.global_member(db, env, name);
            if let PlaceAndQualifiers {
                place: Place::Defined(place),
                qualifiers,
            } = result
                .unwrap_or_else(|error| error.fallback_member(db))
                .member(db)
            {
                if place.definedness == Definedness::PossiblyUndefined {
                    possibly_missing();
                }
                let member = Self::Member {
                    place,
                    qualifiers,
                    error: result.err(),
                };
                if !qualifiers.contains(TypeQualifiers::FROM_MODULE_GETATTR) {
                    return member;
                }
                // Prefer a real submodule over the value or error from module __getattr__.
                from_getattr = Some(member);
            }
        }

        // The index records plain imports such as `import pkg.child`. For
        // `from pkg import child`, we discover the submodule only after looking up the member.
        let full_name = ModuleName::new(name).map(|child| {
            let mut full_name = module.name(db).clone();
            full_name.extend(&child);
            full_name
        });
        let importing_file = ImportingFile::File(file.file(db), env.resolver_environment(db));
        if let Some(submodule) = full_name
            .as_ref()
            .and_then(|name| resolve_module(db, importing_file, name))
        {
            return Self::Submodule(ModuleLiteralType::for_import(db, file, submodule));
        }
        from_getattr.unwrap_or(Self::Missing(full_name))
    }
}

