class Box[C]:
    @staticmethod
    def get[**P](f: Callable[P, int]) -> C:
        def check(other: Box[Callable[P, int]], f: Callable[[int], int]):
            callback = other.get(f)
            reveal_type(callback)
            callback(1)
        raise NotImplementedError
```

