+fn has_include_in_schema_false(call: &ExprCall) -> bool {
+    let Some(keyword) = call.arguments.find_keyword("include_in_schema") else {
+        return false;
+    };
+    matches!(
+        &keyword.value,
+        Expr::BooleanLiteral(ast::ExprBooleanLiteral { value: false, .. })
