+        // Iterate over all nodes and return the dependency-respecting order
+        let mut result = Vec::with_capacity(nodes.len());
+        for idx in 0..nodes.len() {
+            emit_deps(
+                idx,
+                &self.dependencies,
+                &mut emitted,
+                &mut visiting,
+                &mut stack,
+                &mut result,
